// CRITICAL FIX: Even if last exit was same-candle with eligible price, we still need to check
// if the opposite figure (opposite trigger) was crossed before allowing consecutive same-direction trades.
// The business rule is: Consecutive same-direction trades are ONLY allowed if price passes the opposite figure.
// If price hasn't passed the opposite figure, we must alternate regardless of same-candle eligibility.
let mustAlternate = (state.lastExitNote === "SL Hit" || state.lastExitNote === "PT Hit") && state.lastTradeDirection !== null;

// Check if opposite figure was crossed since last trade exit
// This allows consecutive same-direction trades ONLY if opposite trigger was crossed
let oppositeFigureCrossed = false;
if (mustAlternate && state.lastTradeDirection !== null) {
  // Check candles from last exit to current scan start to see if opposite trigger was crossed
  // We need to track this in state, but for now, we'll check during the scan
  // For now, we'll enforce alternation unless same-candle eligible AND we verify opposite figure was crossed
  // The same-candle exception should only apply if we can verify the opposite figure was crossed
  // Since we can't easily verify this without scanning, we'll be conservative and require alternation
  // unless it's a same-candle exit AND we explicitly track opposite figure crossing
  oppositeFigureCrossed = state.lastExitWasSameCandleEligible; // Temporary: same-candle eligible implies price was in zone, but doesn't guarantee opposite figure crossed
}

// Only override alternating logic if same-candle exit AND we can verify opposite figure was crossed
// For now, we'll be conservative: require alternation unless explicitly verified
if (mustAlternate && state.lastExitWasSameCandleEligible) {
  // Same-candle exit with eligible price: check if we should still require alternation
  // The bug shows that consecutive longs occurred without opposite figure being crossed
  // So we should require alternation even for same-candle exits unless opposite figure is verified
  // For safety, we'll require alternation unless we can explicitly verify opposite figure was crossed
  // Since we don't have that tracking yet, we'll require alternation for now
  mustAlternate = true; // Force alternation even for same-candle exits (conservative fix)
  state.log(`  *** Same-candle exit detected, but requiring alternation to prevent consecutive same-direction trades ***`);
}

let requiredDirection = mustAlternate 
  ? (state.lastTradeDirection === "long" ? "short" : "long")
  : null;

