// BUG FIX (2025-12-18): The same-candle exception was allowing consecutive same-direction trades
// without verifying that the opposite figure (opposite trigger) was crossed.
// 
// Context: The same-candle exception (`lastExitWasSameCandleEligible`) was added to allow
// reentry when exit happens on the same candle as entry AND price is in the eligible zone.
// However, this exception is too permissive - it allows consecutive same-direction trades
// without checking if the opposite figure was crossed.
//
// Business rule: Consecutive same-direction trades are ONLY allowed if price passes the
// opposite figure. If price hasn't passed the opposite figure, we must alternate.
//
// Current fix: Require alternation even for same-candle exits unless we can verify the
// opposite figure was crossed (which we'll track in a future enhancement).
let mustAlternate = (state.lastExitNote === "SL Hit" || state.lastExitNote === "PT Hit") && state.lastTradeDirection !== null;

// Even for same-candle exits, require alternation unless opposite figure was crossed
// This prevents consecutive same-direction trades within the same candle interval
// TODO: Track opposite figure crossing to allow same-direction trades when appropriate
if (mustAlternate && state.lastExitWasSameCandleEligible) {
  // Same-candle exit with eligible price: still require alternation to prevent consecutive same-direction trades
  // The bug shows that consecutive longs occurred without opposite figure being crossed
  // For safety, we'll require alternation even for same-candle exits until we can verify opposite figure crossing
  mustAlternate = true; // Force alternation even for same-candle exits (conservative fix)
  state.log(`  *** Same-candle exit detected, but requiring alternation to prevent consecutive same-direction trades (opposite figure not verified) ***`);
}

let requiredDirection = mustAlternate 
  ? (state.lastTradeDirection === "long" ? "short" : "long")
  : null;
